  "بيانات الشركة للعرض فقط: هي نفسها المطبوعة على الفواتير والمسجلة لدى هيئة الزكاة والضريبة (ZATCA)، وتغييرها يتم بطلب تطوير مع تحديث شهادة الربط. نسبة الضريبة وطريقة احتسابها تُضبط في الفاتورة وإعدادات المحاسبة.": "Company details are read-only: they are the same details printed on invoices and registered with ZATCA, and changing them requires a development request with a renewed integration certificate. The VAT rate and calculation are set on the invoice and in the accounting settings.",
