// HR-11: الساعات الإضافية لفترة (من / إلى)
Object.assign(translations, {
  "مجموع ساعات الفترة": "Total hours for the period",
  "عدد الساعات هو مجموع ساعات الفترة كلها (نفس التاريخ في «من» و«إلى» = يوم واحد). الفترة داخل شهر واحد وتدخل راتب ذلك الشهر بعد اعتمادها، ولا يُحسب يوم مرتين":
    "Hours are the total for the whole period (the same date in From and To means one day). The period must be within one month and goes into that month's payroll once approved, and a day is never counted twice",
  "المبلغ = الساعات × (أجر الساعة الفعلي + 50% من أجر الساعة الأساسي) وفق المادة 107 من نظام العمل؛ أجر الساعة الأساسي = الراتب الأساسي ÷ 30 ÷ ساعات العمل اليومية، وأجر الساعة الفعلي = إجمالي الراتب (أو الأساسي إن لم يُسجَّل) ÷ 30 ÷ ساعات العمل اليومية؛ ساعات العمل اليومية من جدول دوام الموظف، وإلا من ملفه. يُتخطى من لم يُسجَّل راتبه الأساسي ومن لديه ساعات إضافية مسجلة في أيام الفترة":
    "Amount = hours × (actual hourly wage + 50% of the basic hourly wage) per Article 107 of the Labor Law; basic hourly wage = basic salary ÷ 30 ÷ daily working hours, and actual hourly wage = total salary (or basic if not recorded) ÷ 30 ÷ daily working hours; daily working hours come from the employee's work schedule, otherwise from their file. Employees without a basic salary, or with overtime already recorded on days of the period, are skipped",
  "فترة الساعات الإضافية يجب أن تكون داخل شهر واحد (شهر الراتب)": "The overtime period must be within one month (the payroll month)",
  "عدد الساعات لا يتجاوز 24 ساعة لكل يوم من أيام الفترة": "Hours cannot exceed 24 for each day of the period",
  "موظف لديه ساعات إضافية مسجلة في أيام هذه الفترة": "employee(s) who already have overtime recorded on days in this period",
  "موظف لديه ساعات إضافية مسجلة في هذا التاريخ": "employee(s) who already have overtime recorded on this date",
  "لا تُسجَّل ساعات إضافية بتاريخ مستقبلي": "Overtime cannot be recorded for a future date",
  "عدد الساعات يجب أن يكون أكبر من صفر، ولا يتجاوز 24 ساعة لكل يوم (لليوم الواحد، أو لكل يوم من أيام الفترة)": "Hours must be greater than zero and cannot exceed 24 per day (for a single day, or for each day of the period)",
  "للموظف ساعات إضافية مسجلة في يوم من أيام هذه الفترة (ليوم أو لفترة)؛ لا يُحسب اليوم مرتين": "The employee already has overtime recorded on a day in this period (for a day or a period); a day is not counted twice",
  "تسجيل الساعات الإضافية لفترة يحتاج تحديث قاعدة البيانات (HR-11)؛ سجّل يومًا واحدًا حتى يُطبَّق": "Recording overtime for a period needs the database update (HR-11); record a single day until it is applied",
  "التاريخ / الفترة": "Date / period",
});

