  "حذف السلفة": "Delete the advance",
  "للعرض فقط: بنود «البدل المخصوم» القديمة المسجلة في ملف الموظف، ويخصمها مسير الرواتب من راتب كل شهر يقع ضمن فترتها. الاقتطاعات الجديدة تُضاف في جدول الاقتطاعات الشهرية أعلاه.": "View only: the old \"deducted allowance\" items in the employee file, which payroll deducts every month in their period. New deductions are added in the monthly deductions table above.",
  "السلفة تُسجَّل معتمدة ويُخصم قسطها من الراتب ابتداءً من شهر البداية حتى السداد. تُعدَّل، ويُؤجَّل قسط شهر (يمتد السداد شهرًا)، وتُحذف ما لم يُخصم منها شيء. المتبقي يُحسب من الأقساط المخصومة فعلًا في كشوف الرواتب.": "An advance is recorded as approved and its installment is deducted from the salary from the start month until repaid. It can be edited, a month's installment can be postponed (repayment extends by one month), and it can be deleted while nothing has been deducted from it. The remaining balance is calculated from the installments actually deducted in payroll statements.",
  "بنود «البدل المخصوم» في ملف الموظف": "\"Deducted allowance\" items in the employee file",
  "حذف السجلات المحددة؟ تخرج من كشف الراتب، ولا يُحذف سجل في شهر رواتبه معتمدة أو مرحّلة": "Delete the selected records? They leave the payroll statement; a record in a month with approved or posted payroll is not deleted",
  "تُسجَّل الساعات الإضافية من «حساب الدوام» معتمدة وتدخل كشف الراتب مباشرة. السجل الخاطئ يُحذف من هنا ويُسجَّل من جديد ما دام شهر رواتبه غير مقفل. السجلات المعلقة القديمة يعتمدها أو يرفضها مسؤول غير من سجّلها": "Overtime recorded from \"Attendance calculation\" is approved and goes into the payroll statement directly. A wrong record is deleted here and entered again while its payroll month is not locked. Old pending records are approved or rejected by an officer other than the one who recorded them",
  "حذف المحدد": "Delete selected",
