  "تم تسجيل الساعات الإضافية (تدخل كشف الراتب) لـ": "Overtime recorded (goes into the payroll statement) for",
  "عدد الساعات هو مجموع ساعات الفترة كلها (نفس التاريخ في «من» و«إلى» = يوم واحد). الفترة داخل شهر واحد وتدخل راتب ذلك الشهر مباشرة، ولا يُحسب يوم مرتين": "The number of hours is the total for the whole period (the same date in \"From\" and \"To\" = one day). The period is within one month and goes into that month's salary directly; no day is counted twice",
