  "خُصم من الموظف قسط سلفة منذ شهر بداية هذه السلفة؛ لا تُحذف ولا يتغير شهر بدايتها. عدّل مبلغها، أو أجّل قسط شهر": "An advance installment has been deducted from the employee since this advance's start month; it cannot be deleted and its start month cannot change. Edit its amount, or postpone a month's installment",
