  "إجمالي استقطاع السلف يحتاج تحديث قاعدة البيانات (HR-13)؛ احفظ دون استقطاع السلف أو طبّق التحديث": "The total advances deduction needs the database update (HR-13); save without the advances deduction or apply the update",
  "الساعات الإضافية المعتمدة أو المرفوضة لا تُعدَّل؛ احذفها من صفحة «الساعات الإضافية» وسجّلها من جديد": "Approved or rejected overtime cannot be edited; delete it from the \"Overtime\" page and enter it again",
  "السلفة المرفوضة لا تُعدَّل": "A rejected advance cannot be edited",
  "يُعدَّل في السلفة المبلغ والقسط وشهر البداية والملاحظات فقط؛ الموظف لا يتغير (احذفها وسجّلها من جديد)": "Only the amount, installment, start month and notes of an advance can be edited; the employee cannot change (delete it and record it again)",
  "استقطاع السلف يسجّله من يدير الرواتب؛ يبقى صفرًا": "The advances deduction is recorded by whoever manages payroll; it stays zero",
