  "طلب عوضًا عن الموظف: يُرسل بلا توقيعه، ويُسجَّل اسمك مرسلًا له": "Request on behalf of the employee: sent without their signature, with your name recorded as the sender",
  "لم يُحذف شيء": "Nothing was deleted",
  "المبلغ = الساعات × الراتب الأساسي ÷ 30 ÷ ساعات العمل اليومية × 1.5 (إعداد الشركة كما في سمارت)؛ ساعات العمل اليومية من جدول دوام الموظف، وإلا من ملفه. يُتخطى من لم يُسجَّل راتبه الأساسي ومن لديه ساعات إضافية مسجلة في أيام الفترة": "Amount = hours × basic salary ÷ 30 ÷ daily working hours × 1.5 (company setting, as in Smart); daily working hours come from the employee's work schedule, otherwise from their file. Employees with no basic salary, or with overtime already recorded on days in the period, are skipped",
