  "إجمالي الساعات المعتمدة": "Total approved hours",
  "إجمالي مبلغ الإضافي المعتمد": "Total approved overtime amount",
  "ساعات معلقة (لا تدخل الراتب)": "Pending hours (not in payroll)",
  "الساعات المعتمدة": "Approved hours",
