  "توجد": "There are",
  "شهادة محفوظة على هذا الجهاز فقط": "certificate(s) saved on this device only",
  "قد تكون حُذفت من قاعدة البيانات عمدًا من جهاز آخر. ارفع فقط ما تتأكد أنه صادر فعلًا، وتجاهل الباقي.": "They may have been deleted from the database intentionally from another device. Upload only those you are sure were actually issued, and ignore the rest.",
  "رفعها": "Upload",
  "تجاهلها": "Ignore",
  "تم حفظ إعدادات حساب الراتب؛ تُطبَّق على الكشوف التي تُحسب أو يُعاد إرسالها بعد الآن": "Payroll settings saved; they apply to payroll statements calculated or resubmitted from now on",
  "المطبّق في كشف الرواتب وحساب الدوام:": "Applied in the payroll statement and attendance calculation:",
  "طريقة احتساب قيمة أيام الغياب، وطريقة حساب أيام الشهر، واستثناء السلف من الاقتطاعات، ونظام الراتب المكتسب حسب الحضور. الحقول المعلَّمة «مطبّق» تغيّر الأرقام مباشرة؛ الباقي يُحفظ ولا يُستخدم بعد.": "How absence days are valued, how month days are counted, excluding advances from deductions, and the attendance-based earned salary system. Fields marked \"Applied\" change the figures directly; the rest are saved but not used yet.",
  "خيار «البدلات + الامتيازات» يُحسب حاليًا كالبدلات لعدم وجود امتيازات مسجلة للموظفين.": "The \"Allowances + benefits\" option is currently calculated as allowances, since no benefits are recorded for employees.",
  "الإجازات: نوع «مدفوعة = لا» يُخصم يومه كاملًا، ونسبة الخصم في تصنيفات الإجازات تُطبّق، والمرضية حسب المادة 117 (30 يومًا كاملة، ثم 60 بثلاثة أرباع، ثم 30 بلا أجر)، بالأيام التقويمية. من لم يعمل أي يوم في الشهر (غياب أو إجازة بدون راتب في كل أيام عمله) لا يُستحق له أجر الشهر.": "Leaves: a type with \"Paid = No\" deducts the full day, the deduction percentage in leave classifications is applied, and sick leave follows Article 117 (30 days at full pay, then 60 at three-quarters, then 30 unpaid), in calendar days. An employee who did not work any day in the month (absent or on unpaid leave on all working days) is not entitled to that month's wage.",
  "مطبّق": "Applied",
  "غير مطبّق": "Not applied",
  "لا: يُخصم الغياب المسجَّل في الحضور فقط (حالة «غائب»). نعم: كل يوم عمل ماضٍ ليس فيه تسجيل حضور ولا إجازة معتمدة ولا عطلة يُحتسب غيابًا ويُخصم، إلا للموظف المعفى من الحضور.": "No: only absences recorded in attendance are deducted (\"Absent\" status). Yes: every past working day with no attendance record, approved leave or holiday counts as an absence and is deducted, except for employees exempt from attendance.",
  "تنبيه: فعّله فقط إذا كان كل الموظفين يسجلون حضورهم يوميًا؛ وإلا خُصمت أيام موظفين لا يستخدمون البصمة.": "Caution: enable it only if all employees record their attendance daily; otherwise days will be deducted from employees who do not use the fingerprint.",
  "اتباع حقل التأمينات الاجتماعية في ملف الموظف": "Follow the social insurance field in the employee file",
  "لا (الافتراضي): تُخصم حصة الموظف في التأمينات من كل موظف سعودي، إلا نوع «سعودي غير قابل للخصم». نعم: الموظف السعودي المسجّل في ملفه «غير مشمول» لا يُخصم منه.": "No (default): the employee's insurance share is deducted from every Saudi employee, except the \"Saudi, non-deductible\" type. Yes: a Saudi employee whose file is marked \"Not covered\" is not deducted.",
  "تنبيه: نموذج الموظف القديم كان يحفظ «لا» تلقائيًا. راجع صفحة التأمينات الاجتماعية وصحّح ملفات السعوديين قبل التفعيل.": "Caution: the old employee form saved \"No\" automatically. Review the social insurance page and correct Saudi employees' files before enabling.",
  "أجر الاشتراك في التأمينات يشمل بدل السكن": "Insurance contribution wage includes housing allowance",
  "لا (الافتراضي): حصة الموظف من الراتب الأساسي فقط كما كانت. نعم: من الأساسي + بدل السكن بحد 45,000 كما في نظام التأمينات. اختر ما يطابق الأجر المسجّل لموظفيك في التأمينات الاجتماعية، فالخصم يجب أن يساوي ما تطالب به التأمينات.": "No (default): the employee share is from the basic salary only, as before. Yes: from basic + housing allowance, capped at 45,000 as in the social insurance law. Choose what matches the wage registered for your employees with social insurance, since the deduction must equal what social insurance claims.",
  "تعذر تحميل الإعدادات المحفوظة؛ الحفظ معطّل حتى لا تُستبدل بالقيم الافتراضية": "Could not load the saved settings; saving is disabled so they are not replaced with default values",
  "الاشتراك الشهري المتوقع من بيانات ملف الموظف وإعدادات حساب الراتب: أجر الاشتراك = الأساسي (أو الأساسي + بدل السكن إن فُعّل الإعداد)، بحد 45,000. السعودي: 9.75% على الموظف و11.75% على المنشأة. غير السعودي: 2% على المنشأة فقط": "Expected monthly contribution based on employee file data and payroll settings: contribution wage = basic (or basic + housing allowance if the setting is enabled), capped at 45,000. Saudi: 9.75% employee and 11.75% employer. Non-Saudi: 2% employer only",
  "السعودي المسجّل أول مرة في التأمينات من 3 يوليو 2024 (نوع «النظام الجديد» في ملفه): نسبة المعاشات ترتفع 0.5% كل يوليو على الطرفين حتى 11% في 2028": "Saudis first registered with social insurance from 3 July 2024 (\"New system\" type in their file): the pension rate rises 0.5% every July for both parties, up to 11% in 2028",
  "موظف سعودي ملفه «غير مشمول» وتُخصم منه حصة التأمينات لأن إعداد «اتباع حقل التأمينات» مطفأ. إن كان غير مشمول فعلًا فصحّح ملفات البقية ثم فعّل الإعداد من إعدادات حساب الراتب": "Saudi employee(s) whose file is \"Not covered\" but who have the insurance share deducted because the \"Follow the insurance field\" setting is off. If they are truly not covered, correct the other files, then enable the setting in Payroll settings",
  "تعذر قراءة إعدادات حساب الراتب؛ الأرقام بالإعداد الافتراضي": "Could not read payroll settings; figures use the default settings",
  "بحث بالاسم أو الرقم الوظيفي...": "Search by name or employee number...",
  "يُخصم": "Deducted",
