  "تعذر حذف الشركة": "Could not delete the company",
  "هذه القائمة لا تُستخدم في حساب الدوام. جداول الدوام التي يُربط بها الموظف وتُحسب بها الساعات والتأخير في: إعداد فترات الدوام": "This list is not used in attendance calculation. Work schedules that employees are linked to, and that hours and lateness are calculated from, are in: Work schedule settings",
  "فتح إعداد فترات الدوام": "Open work schedule settings",
