  "لم يُحذف شيء: السجل مرحّل أو لا تملك صلاحية حذفه": "Nothing was deleted: the record is posted or you do not have permission to delete it",
  "رواتب هذا الشهر معتمدة أو مرحّلة؛ لا يُحذف جزاء خُصم منها": "This month's salaries are approved or posted; a penalty deducted from them cannot be deleted",
  "تعذّر التحقق من رواتب الشهر": "Could not verify the month's salaries",
  "لم يُحذف شيء: السجل غير موجود أو لا تملك صلاحية حذفه": "Nothing was deleted: the record does not exist or you do not have permission to delete it",
  "الاستحقاق محسوب من ملف الموظف ونظام العمل فقط": "Entitlement is calculated from the employee file and the Labor Law only",
  "الاستحقاق السنوي: الأعلى من الأيام التعاقدية في ملف الموظف، ونظام العمل (21 يومًا، و30 يومًا بعد خمس سنوات خدمة)، ومدة الإجازة السنوية في تصنيف الإجازات. يُحتسب نسبيًا من بداية السنة أو تاريخ التعيين، والمستخدم = أيام الإجازات السنوية المعتمدة داخل السنة الحالية.": "Annual entitlement: the highest of the contractual days in the employee file, the Labor Law (21 days, and 30 days after five years of service), and the annual leave duration in leave classifications. It is prorated from the start of the year or the hire date, and used = approved annual leave days within the current year.",
  "الأرصدة محسوبة من الإجازات المعتمدة المسجلة في النظام": "Balances are calculated from approved leaves recorded in the system",
  "إخفاء التفاصيل": "Hide details",
