  "لديه بريد محفوظ. إعادة التوليد تغيّر كلمة مرور بريده، ويلزم إبلاغه بالجديدة. متابعة؟": "already has a saved email. Regenerating changes their email password, and they must be informed of the new one. Continue?",
  "تم توليد وحفظ البريد وكلمة المرور وربطهما بالموظف": "Email and password generated, saved and linked to the employee",
  "إيميلات الموظفين": "Employee emails",
  "توليد الإيميلات": "Generate emails",
  "يُولَّد للموظف بريد داخلي وكلمة مرور ويُربطان بملفه، فيدخل بهما إلى بريده من بوابة الموظف.": "An internal email and password are generated for the employee and linked to their file, so they can sign in to their mailbox from the employee portal.",
  "اختر موظف": "Select employee",
  "لديه بريد": "Has email",
