  "نسخ": "Copy",
  "سلّمها للموظف ليدخل بريده من البوابة. تظهر كلمة المرور هنا مرة واحدة، وفي القائمة لمدير النظام فقط.": "Give them to the employee to sign in to their mailbox from the portal. The password is shown here once, and in the list to the system administrator only.",
