  "أكمل بيانات قائمة المكونات وتأكد من عدم تكرار المواد أو استخدام المنتج النهائي كمكوّن": "Complete the bill of materials and make sure no material is repeated and the finished product is not used as a component",
  "أكمل بيانات أمر التصنيع": "Complete the manufacturing order details",
  "تم حفظ أمر التصنيع كمسودة": "Manufacturing order saved as draft",
  "هل تريد ترحيل أمر التصنيع؟ سيتم صرف المكونات واستلام المنتج النهائي وإنشاء القيد المحاسبي، ولن يمكن تعديل الأمر بعد ذلك.": "Post the manufacturing order? Components will be issued, the finished product received and the journal entry created; the order cannot be edited afterwards.",
