  "لم يُحذف أي سجل: لا توجد سجلات تحضير إداري في الفترة أو لا تملك صلاحية الحذف": "No record was deleted: there are no administrative attendance records in the period, or you do not have delete permission",
  "سجل يحمل بصمة موثّقة من بوابة الموظف دون حذف": "record(s) with a verified punch from the employee Portal (not deleted)",
  "ولم يُمس": "and",
  "شهر رواتبه معتمدة أو مرحّلة لموظف": "employee month(s) with approved or posted payroll were not touched",
  "سيتم مسح وقت الدخول والخروج من سجلات الحضور (حاضر/متأخر) في أيام عمل كل موظف حسب جدول دوامه فقط، وتتحول حالة اليوم إلى غائب فيُخصم من الراتب؛ لا تُمس أيام الراحة ولا العطل الرسمية ولا الإجازات المعتمدة ولا سجلات الإجازة والمأمورية والعمل عن بعد، ولا بصمات الموظفين الموثّقة من البوابة": "Check-in and check-out times will be cleared from attendance records (present/late) only on each employee's work days per their work schedule, and the day becomes absent and is deducted from salary; rest days, public holidays, approved leaves, leave, business errand and remote work records, and employee punches verified from the Portal are not touched",
  "الأيام بلا تسجيل تُحتسب غيابًا (إعداد الراتب المكتسب حسب الحضور): يوم العمل الماضي بلا أي تسجيل يظهر «غائب (بلا تسجيل)» ويُخصم من الراتب.": "Days without records count as absence (attendance-based earned salary setting): a past work day with no record shows \"Absent (no record)\" and is deducted from salary.",
  "الغياب = غياب مسجّل صراحة (حالة غائب) ويُخصم من الراتب؛ يوم العمل الماضي بلا أي تسجيل يظهر «لا يوجد تسجيل» ولا يُحتسب غيابًا ما لم يُفعَّل إعداد «الراتب المكتسب حسب الحضور» في إعدادات حساب الراتب.": "Absence = explicitly recorded absence (Absent status), deducted from salary; a past work day with no record shows \"No record\" and is not counted as absence unless the \"Attendance-based earned salary\" setting is enabled in payroll settings.",
  "أيام العمل والساعات المستحقة والتأخير والخروج المبكر حسب جدول دوام كل موظف (من لا جدول له: الأحد إلى الخميس)، وهي القاعدة نفسها المستخدمة في كشف الرواتب.": "Work days, required hours, lateness and early leave follow each employee's work schedule (no schedule: Sunday to Thursday), the same rule used in the payroll statement.",
