  "تم حفظ الفترة المالية": "Fiscal period saved",
  "سيتم منع ترحيل القيود وحركات المخزون داخل هذه الفترة، مع بقاء المسودات قابلة للحفظ. هل تريد إغلاقها؟": "Posting journal entries and stock movements within this period will be blocked, while drafts can still be saved. Close it?",
  "سيتم السماح بالترحيل داخل هذه الفترة مجددًا. هل تريد فتحها؟": "Posting within this period will be allowed again. Reopen it?",
