  "حسابات الترحيل الافتراضية": "Default posting accounts",
  "تستخدمها قيود المبيعات والمشتريات والضريبة وتسويات المخزون. الحسابات التجميعية غير متاحة.": "Used by sales, purchases, tax and inventory adjustment entries. Group accounts are not available.",
  "العملة الأساسية": "Base currency",
