  "الفترات المالية": "Fiscal periods",
  "الترحيل المحاسبي وحركات المخزون متاحان فقط داخل فترة مفتوحة. إغلاق الفترة لا يمنع حفظ مسودات القيود.": "Accounting posting and stock movements are allowed only within an open period. Closing a period does not prevent saving journal entry drafts.",
  "فترة مالية جديدة": "New fiscal period",
  "اسم الفترة": "Period name",
  "حفظ الفترة": "Save period",
  "لا توجد فترات مالية معرفة": "No fiscal periods defined",
  "يجب أن يقع تاريخ أي ترحيل محاسبي أو حركة مخزون داخل فترة مالية مفتوحة. يمكن حفظ مسودة القيد خارج الفترة المفتوحة، لكن لا يمكن ترحيلها حتى فتح الفترة المناسبة.": "The date of any accounting posting or stock movement must fall within an open fiscal period. A journal entry draft can be saved outside an open period, but it cannot be posted until the relevant period is opened.",
  "مستوى القسم الفرعي يحسم إن حُدد، وإلا يسري مستوى القسم الرئيسي عليه. مثال: الموارد البشرية «إدارة كاملة» والرواتب «لا وصول» = لا يفتح صفحات الرواتب ولا يعدّلها ولا يعتمدها، ويبقى ما تعرضه تقارير الموارد البشرية لمن له التقارير.": "The sub-section level prevails if set; otherwise the main section level applies to it. Example: Human resources \"Full management\" and Payroll \"No access\" = cannot open, edit or approve payroll pages, while what HR reports show stays available to those with reports access.",
  "لا يمنح أحد دورًا صلاحية أعلى من صلاحياته هو، ولا يُسند لموظف دورًا فوق صلاحياته؛ ذلك لمدير النظام.": "No one can grant a role more permissions than their own, or assign an employee a role above their own permissions; that is for the system administrator.",
  "أدخل التاريخ والوصف وحسابًا وطرفًا واحدًا مدينًا أو دائنًا لكل سطر": "Enter the date, the description, and for each line an account and a single debit or credit amount",
  "تم حفظ القيد كمسودة": "Journal entry saved as draft",
