  "أُضيفت رواتب بعد ترحيل الشهر؛ لا تُرحَّل بقيده (احذفها وأضفها في الشهر التالي أو بقيد تسوية)": "Payroll was added after the month was posted; it is not posted with its journal entry (delete it and add it in the next month or via an adjustment entry)",
