  "ترحيل استحقاقات واستقطاعات رواتب الفترة المحددة إلى النظام المحاسبي بقيد واحد، بعد اعتماد كل رواتب الشهر. بعد الترحيل تتحول حالة السجل إلى «مرحّل» ولا يُرحّل مرة أخرى.": "Post the accrued earnings and deductions of the selected period's payroll to accounting in a single journal entry, after all payroll for the month is approved. After posting, the record status changes to \"Posted\" and it cannot be posted again.",
  "مصروف الرواتب = الاستحقاقات بعد خصم الغياب والإجازات غير المدفوعة والبدلات المخصومة. الراتب الموقوف (بموافقة الإدارة) يُستحق في القيد ويُحبس صرفه حتى رفع الإيقاف من هذه الصفحة. لا يُرحَّل راتب تغيّر بعد موافقة الإدارة.": "Payroll expense = earnings after deducting absences, unpaid leave and deducted allowances. A suspended salary (approved by management) is accrued in the entry and its payment is held until the hold is released from this page. A salary changed after management approval is not posted.",
