  "الأرصدة الافتتاحية للمخزون": "Inventory opening balances",
  "إثبات الكميات والتكلفة عند بدء استخدام النظام مع قيد افتتاحي متوازن، مرة واحدة لكل صنف ومستودع.": "Record quantities and costs when you start using the system, with a balanced opening entry, once per item and warehouse.",
