  "استخدم هذه الشاشة فقط للأرصدة السابقة لبدء التشغيل. لا يمكن إدخال رصيد افتتاحي لصنف ومستودع توجد لهما حركة سابقة، ولا تُرسل هذه العملية إلى ZATCA.": "Use this screen only for balances prior to go-live. An opening balance cannot be entered for an item and warehouse that already have movements, and this operation is not sent to ZATCA.",
