  "تعذر تحميل حالات رواتب الشهر؛ لا يمكن الإرسال الآن": "Could not load this month's payroll statuses; cannot submit now",
  "موظف رواتبهم معتمدة أو مرحّلة لهذا الشهر؛ لن يُعاد إرسالها ولا تُوقف من هنا": "employees whose payroll is approved or posted for this month; it will not be resubmitted or suspended from here",
  "الشهر لم ينتهِ بعد: الغياب الذي يُسجَّل بعد اليوم لن يدخل هذا الكشف إذا اعتُمد الآن": "The month has not ended yet: absences recorded after today will not be included in this statement if it is approved now",
  "الموقوفون فقط": "Suspended only",
  "إلغاء كل الإيقاف": "Unsuspend all",
  "إيقاف الراتب": "Suspend salary",
  "إيقاف راتب": "Suspend salary of",
  "سبب الإيقاف (يظهر للإدارة في الطلب)": "Suspension reason (shown to management in the request)",
  "الراتب الموقوف يُحفظ في كشف الشهر بحالة «موقوف» ويُعرض على الإدارة ضمن الطلب. بعد موافقة الإدارة يُرحَّل استحقاقه في قيد الشهر (مصروفًا والتزامًا للموظف) ويُحبس صرفه حتى يُرفع الإيقاف من صفحة الترحيل. لإلغاء الإيقاف قبل الاعتماد: أعد إرسال الطلب دون تحديد الموظف.": "A suspended salary is saved in the month's statement with the status \"Suspended\" and shown to management in the request. After management approves, its accrual is posted in the month's journal entry (as an expense and a liability to the employee) and its payment is held until the suspension is lifted from the posting page. To cancel the suspension before approval: resubmit the request without selecting the employee.",
  "إرسال طلب الاعتماد": "Submit approval request",
  "جاري تحميل حالات رواتب الشهر...": "Loading this month's payroll statuses...",
  "لا يوجد راتب يُرسل للاعتماد (كلها معتمدة أو مرحّلة مسبقًا)": "No salary to send for approval (all are already approved or posted)",
  "كل المحددين موقوفون: يُرسل الطلب لاعتماد إيقافهم فقط": "All selected are suspended: the request is sent only to approve their suspension",
  "لا يُحذف ولا يُعطّل من هنا": "Cannot be deleted or deactivated from here",
  "الحذف متاح فقط لموظف ليس له أي سجلات (حضور، رواتب، طلبات...).": "Deletion is only available for an employee with no records (attendance, payroll, requests...).",
  "دور هذا الموظف فيه صلاحيات أعلى من صلاحياتك؛ يحذفه أو يعطّله مدير النظام": "This employee's role has higher permissions than yours; the system administrator must delete or deactivate them",
