  "لم يُوقف حساب الدخول": "The login was not stopped",
  "جارٍ التحقق من أن الرواتب المحفوظة تطابق الحضور والغياب الحالي...": "Checking that the saved payroll matches current attendance and absences...",
  "تعذر التحقق من مطابقة الرواتب المحفوظة للحساب الحالي": "Could not verify that the saved payroll matches the current calculation",
  "أرقام هذا الطلب قديمة: لا تعتمده": "This request's figures are outdated: do not approve it",
  "أُدخل حضور أو غياب أو جزاء بعد إرسال الطلب، فالصافي المعروض عليك لم يعد صحيحًا ولو اعتُمد لصُرف الصافي القديم. ارفض الطلب ليعيد مسؤول الرواتب إرساله بالأرقام الحالية.": "Attendance, absence or a penalty was entered after the request was sent, so the net shown to you is no longer correct; if approved, the old net would be paid. Reject the request so the payroll officer can resubmit it with current figures.",
  "حضور أو غياب لأيام بعد يوم إرسال الطلب": "Attendance or absence for days after the request date",
  "سُجّلت أيام بعد يوم إرسال الطلب تغيّر صافي هؤلاء. الأفضل رفض الطلب ليعيد مسؤول الرواتب إرساله؛ وإن اعتمدته يُصرف الصافي كما أُرسل.": "Days recorded after the request date change these employees' net. It is best to reject the request so the payroll officer can resubmit it; if you approve it, the net is paid as submitted.",
  "طلب الاعتماد فيه أرقام قديمة": "The approval request has outdated figures",
  "حُفظت هذه الرواتب للاعتماد قبل آخر إدخال للحضور أو الغياب أو الجزاءات، ولو اعتُمدت لصُرف الصافي القديم. أعد إرسال الكشف للاعتماد: يحل الطلب الجديد محل طلبك المعلق بالأرقام الحالية.": "This payroll was saved for approval before the latest attendance, absence or penalty entry; if approved, the old net would be paid. Resubmit the statement for approval: the new request replaces your pending request with current figures.",
  "طلب اعتماد لمستخدم آخر فيه أرقام قديمة": "Another user's approval request has outdated figures",
  "هذه الرواتب في طلب اعتماد معلق أرسله مستخدم آخر، فلا يمكنك إعادة إرسالها. اطلب من المعتمد رفض ذلك الطلب، ثم أعد إرسال الكشف.": "This payroll is in a pending approval request sent by another user, so you cannot resubmit it. Ask the approver to reject that request, then resubmit the statement.",
  "رواتب مقرَّرة بأرقام تختلف عن الحساب الحالي": "Finalized payroll with figures that differ from the current calculation",
  "اعتُمدت هذه الرواتب أو رُحّلت أو قُرّر إيقافها بأرقام تختلف عن الحساب الحالي، ولا تتغير بإعادة الإرسال؛ راجعها مع المحاسبة (قيد تسوية).": "This payroll was approved, posted or suspended with figures that differ from the current calculation, and resubmitting will not change it; review it with accounting (adjustment entry).",
