  "«المسدد قبل النظام» يحتاج تحديث قاعدة البيانات (HR-14)؛ احفظ دونه أو طبّق التحديث": "\"Repaid before the system\" requires a database update (HR-14); save without it or apply the update",
  "أحد حسابات الرواتب مضبوط على حساب ضريبة القيمة المضافة؛ صحّحه من إعدادات الحسابات قبل الترحيل": "One of the payroll accounts is set to the VAT account; correct it in the account settings before posting",
