  "الدور مستخدم لموظفين أو مستخدمين خاصين؛ انقلهم إلى دور آخر قبل حذفه": "The role is assigned to employees or special users; move them to another role before deleting it",
  "الدور مستخدم؛ لا يُعاد تسميته. أنشئ دورًا جديدًا وانقل إليه الموظفين": "The role is in use and cannot be renamed. Create a new role and move the employees to it",
  "الراتب أو إيقافه معتمد من الإدارة؛ لا تُعدَّل مبالغه": "The salary or its suspension has been approved by management; its amounts cannot be edited",
  "الراتب ضمن طلب اعتماد معلق عُرض على الإدارة؛ لا تُعدَّل مبالغه حتى يُقرَّر فيه أو يُعاد الإرسال": "The salary is in a pending approval request submitted to management; its amounts cannot be edited until it is decided or resubmitted",
  "الراتب ليس موقوف الصرف بعد الترحيل؛ لا يوجد إيقاف يُرفع": "The salary payment is not suspended after posting; there is no suspension to lift",
  "الراتب مرحّل محاسبيًا ولا يُعدَّل": "The salary is posted to accounting and cannot be edited",
  "الرقم الوظيفي غير موجود": "Employee ID not found",
  "السلفة غير موجودة": "Advance not found",
  "الشهر مرحّل محاسبيًا؛ لا تُضاف إليه رواتب جديدة (أضفها في الشهر التالي أو بقيد تسوية)": "The month is posted to accounting; no new salaries can be added to it (add them in the next month or with an adjustment entry)",
  "الشهر مرحّل مسبقًا وأُضيفت إليه رواتب بعد الترحيل؛ لا تُرحَّل بقيد الشهر (احذفها وأضفها في الشهر التالي أو بقيد تسوية)": "The month was already posted and salaries were added after posting; they cannot be posted with the month's entry (delete them and add them in the next month or with an adjustment entry)",
  "الطلب غير موجود": "Request not found",
  "الطلب ليس طلب اعتماد رواتب": "The request is not a payroll approval request",
  "العنصر مرتبط بموظفين أو بأقسام؛ انقلهم إلى عنصر آخر قبل حذفه": "The item is linked to employees or sections; move them to another item before deleting it",
  "الفترة المالية لهذا الشهر مقفلة": "The fiscal period for this month is closed",
  "الفترة طويلة؛ اختر سنة أو أقل": "The period is too long; choose one year or less",
  "الفترة طويلة؛ اختر شهرين أو أقل": "The period is too long; choose two months or less",
  "القرار لمستلم الطلب فقط": "Only the request recipient can decide",
  "المسدد قبل النظام لا يكون سالبًا": "The amount repaid before the system cannot be negative",
  "المسدد قبل النظام لا يكون سالبًا، ويكون أقل من مبلغ السلفة (السلفة المسددة كلها في سمارت لا تُسجَّل)": "The amount repaid before the system cannot be negative and must be less than the advance amount (an advance fully repaid in Smart is not recorded)",
  "انتهت جلسة الدخول؛ سجّل الدخول من جديد ثم أعد الإرسال": "Your session has expired; sign in again and resubmit",
  "بعض الموظفين المحددين ضمن طلب اعتماد معلق أرسله مستخدم آخر لهذا الشهر؛ انتظر قرار الإدارة أو اطلب منه سحب طلبه أولًا": "Some selected employees are in a pending approval request sent by another user for this month; wait for management's decision or ask them to withdraw their request first",
  "تسجيل الحضور وتعديله وحذفه يتطلب صلاحية إدارة الحضور": "Recording, editing and deleting attendance requires attendance management permission",
  "تسجيل الساعات الإضافية يتطلب صلاحية إدارة الحضور": "Recording overtime requires attendance management permission",
  "تسجيل السلف يتطلب صلاحية إدارة الرواتب": "Recording advances requires payroll management permission",
